solution.code:
from collections import deque


def bangun_graf(daftar_jalan):
    graf = {}
    for baris in daftar_jalan:
        bagian = [b.strip() for b in baris.split("-")]
        if len(bagian) != 2 or not bagian[0] or not bagian[1] or bagian[0] == bagian[1]:
            continue
        a, b = bagian
        graf.setdefault(a, set()).add(b)
        graf.setdefault(b, set()).add(a)
    return {k: sorted(v) for k, v in graf.items()}


def rute_terpendek(graf, a, b):
    if a not in graf or b not in graf:
        return None
    asal = {a: None}
    antrean = deque([a])
    while antrean:
        simpul = antrean.popleft()
        if simpul == b:
            rute = []
            while simpul is not None:
                rute.append(simpul)
                simpul = asal[simpul]
            return rute[::-1]
        for t in graf[simpul]:
            if t not in asal:
                asal[t] = simpul
                antrean.append(t)
    return None


def terjangkau(graf, a):
    if a not in graf:
        return []
    terlihat = {a}
    tumpukan = [a]
    while tumpukan:
        simpul = tumpukan.pop()
        for t in graf[simpul]:
            if t not in terlihat:
                terlihat.add(t)
                tumpukan.append(t)
    return sorted(terlihat)


def jumlah_wilayah(graf):
    terlihat, hitung = set(), 0
    for simpul in graf:
        if simpul not in terlihat:
            terlihat.update(terjangkau(graf, simpul))
            hitung += 1
    return hitung


def tersibuk(graf, n):
    urut = sorted(graf, key=lambda k: (-len(graf[k]), k))
    return urut[:n]

