        d = {}
        for c in t.lower():
            if c != ' ':
                d[c] = d.get(c, 0) + 1
        return d
    return hitung(a) == hitung(b)


def kompres(s):
    if not s:
        return ''
    bagian = []
    saat_ini, jumlah = s[0], 1
    for ch in s[1:]:
        if ch == saat_ini:
            jumlah += 1
        else:
            bagian.append(saat_ini + str(jumlah))
            saat_ini, jumlah = ch, 1
    bagian.append(saat_ini + str(jumlah))
    return ''.join(bagian)

