def seimbang(teks):
    pasangan = {')': '(', ']': '[', '}': '{'}
    tumpukan = []
    for ch in teks:
        if ch in '([{':
            tumpukan.append(ch)
        elif ch in pasangan:
            if not tumpukan or tumpukan.pop() != pasangan[ch]:
                return False
    return not tumpukan


def postfix(token):
    tumpukan = []
    for t in token:
        if t in '+-*/':
            b = tumpukan.pop()
            a = tumpukan.pop()
            if t == '+':
                tumpukan.append(a + b)
            elif t == '-':
                tumpukan.append(a - b)
            elif t == '*':
                tumpukan.append(a * b)
            else:
                tumpukan.append(a / b)
        else:
            tumpukan.append(float(t))
    return tumpukan[0]

