def urut_sisip(a):
    a = a[:]
    for i in range(1, len(a)):
        kunci = a[i]
        j = i - 1
        while j >= 0 and a[j] > kunci:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = kunci
    return a


def gabung(kiri, kanan):
    hasil, i, j = [], 0, 0
    while i < len(kiri) and j < len(kanan):
        if kiri[i] <= kanan[j]:
            hasil.append(kiri[i])
            i += 1
        else:
            hasil.append(kanan[j])
            j += 1
    hasil.extend(kiri[i:])
    hasil.extend(kanan[j:])
    return hasil


def urut_gabung(a):
    if len(a) <= 1:
        return a[:]
    tengah = len(a) // 2
    return gabung(urut_gabung(a[:tengah]), urut_gabung(a[tengah:]))

