def tinggi(akar):
    if akar is None:
        return 0
    return 1 + max(tinggi(akar.kiri), tinggi(akar.kanan))


def inorder(akar):
    if akar is None:
        return []
    return inorder(akar.kiri) + [akar.nilai] + inorder(akar.kanan)


def cari_bst(akar, x):
    while akar:
        if x == akar.nilai:
            return True
        akar = akar.kiri if x < akar.nilai else akar.kanan
    return False

