from collections import deque


def urutan_bfs(graf, mulai):
    terlihat = {mulai}
    antrean = deque([mulai])
    urutan = []
    while antrean:
        simpul = antrean.popleft()
        urutan.append(simpul)
        for t in graf[simpul]:
            if t not in terlihat:
                terlihat.add(t)
                antrean.append(t)
    return urutan


def ada_jalur(graf, a, b):
    terlihat = {a}
    tumpukan = [a]
    while tumpukan:
        simpul = tumpukan.pop()
        if simpul == b:
            return True
        for t in graf[simpul]:
            if t not in terlihat:
                terlihat.add(t)
                tumpukan.append(t)
    return False

