solution.code:
def jumlah_maks(a, k):
    if k <= 0 or k > len(a):
        return None
    jendela = sum(a[:k])
    terbaik = jendela
    for i in range(k, len(a)):
        jendela += a[i] - a[i - k]
        terbaik = max(terbaik, jendela)
    return terbaik


def terpanjang_unik(s):
    posisi = {}
    kiri = terbaik = 0
    for kanan, ch in enumerate(s):
        if ch in posisi and posisi[ch] >= kiri:
            kiri = posisi[ch] + 1
        posisi[ch] = kanan
        terbaik = max(terbaik, kanan - kiri + 1)
    return terbaik
